static unsigned checks,submissions,fail_submit;
#define CHECK(v) do{checks++;if(!(v)){std::fprintf(stderr,"raster batch assertion line%d\n",__LINE__);std::exit(1);}}while(0)
extern "C" VkResult batch_test_submit(VkQueue q,uint32_t n,const VkSubmitInfo *s,VkFence f){unsigned fail=fail_submit;fail_submit=0;auto status=vkQueueSubmit(q,n,s,f);if(status==VK_SUCCESS)++submissions;return fail && status==VK_SUCCESS?VK_ERROR_UNKNOWN:status;}
static int always(void*){return 1;}
static int countdown(void *p){return --*static_cast<unsigned*>(p)==0;}
static void wait(uint64_t d,uint64_t j){SatchelVulkanSubmissionReport r={};CHECK(satchel_vulkan_submission_wait(d,j,5000,nullptr,nullptr,&r)==SATCHEL_VULKAN_OK && r.completed && !r.resources_retained);}
static uint64_t pipeline(uint64_t d,unsigned rgb){RasterFixture v,f;fixture_init(&v,1);fixture_ald(&v,4,0,0,4);fixture_mov(&v,0,4);fixture_ast(&v,0,0,1);fixture_ast(&v,5,1,3);fixture_exit(&v);fixture_init(&f,5);for(unsigned i=0;i<4;i++)fixture_imm(&f,i,(i==3 || (rgb&(1u<<i)))?0x3f800000:0);fixture_exit(&f);auto vi=fixture_input(&v,1),fi=fixture_input(&f,5);SatchelRasterModule vs,fs;CHECK(!satchel_raster_compile_pair(&vi,&fi,&vs,&fs));SatchelVulkanRasterDescription desc={};desc.version=1;desc.size=sizeof(desc);desc.state=vi.state;desc.format=1;desc.samples=1;desc.topology=3;desc.color_mask=15;desc.sample_mask=1;desc.vertex_stride=16;for(auto &x:desc.attribute_offsets)x=UINT32_MAX;desc.attribute_offsets[0]=0;uint64_t p=0;SatchelVulkanRasterInfo info;CHECK(satchel_vulkan_raster_create(d,&desc,&vs,&fs,&p,&info)==SATCHEL_VULKAN_OK && p);return p;}
static SatchelVulkanRasterCommand draw(uint64_t p,uint64_t v,unsigned x,unsigned y,unsigned w,unsigned h){SatchelVulkanRasterCommand c={};c.operation=SATCHEL_VULKAN_RASTER_OP_DRAW;c.pipeline=p;c.vertex_buffer=v;c.vertex_count=3;c.viewport_width=64;c.viewport_height=48;c.max_depth=1;c.scissor_x=x;c.scissor_y=y;c.scissor_width=w;c.scissor_height=h;return c;}
static void paint(std::vector<uint8_t> &expected,size_t offset,size_t pitch,unsigned x,unsigned y,unsigned w,unsigned h,unsigned rgb){for(unsigned yy=y;yy<y+h;yy++)for(unsigned xx=x;xx<x+w;xx++)for(unsigned c=0;c<4;c++)expected[offset+yy*pitch+xx*4+c]=(c==3 || (rgb&(1u<<c)))?255:0;}
static void verify(uint64_t d,uint64_t b,const std::vector<uint8_t> &expected){std::vector<uint8_t> actual(expected.size());CHECK(satchel_vulkan_buffer_read(d,b,0,actual.data(),actual.size())==SATCHEL_VULKAN_OK);for(size_t i=0;i<actual.size();i++)CHECK(actual[i]==expected[i]);}
