 uint64_t red=pipeline(d,1),green=pipeline(d,2),blue=pipeline(d,4);std::vector<uint8_t> expected(size,0xa5),pattern(size,0xa5);for(unsigned y=0;y<48;y++)for(unsigned x=0;x<64;x++){pattern[offset+y*row+x*4]=(uint8_t)(x*3);pattern[offset+y*row+x*4+1]=(uint8_t)(y*5);pattern[offset+y*row+x*4+2]=91;pattern[offset+y*row+x*4+3]=255;}
